func cnfConfigCmpGoKey36(a, b HostKey) int {
	if c := cnfrt.CompareAddr(a.Addr, b.Addr); c != 0 {
		return c
	}
	if c := cmp.Compare(a.Port, b.Port); c != 0 {
		return c
	}
	if c := strings.Compare(string(a.Name), string(b.Name)); c != 0 {
		return c
	}
	return 0
}

func cnfConfigCmpKey36(s *ConfigSnapshot, a flatKeyHostKey, b HostKey) int {
	_ = s
	if c := cnfrt.CompareAddr(cnfrt.DecodeAddr(a.FAddr, s.zoned), b.Addr); c != 0 {
		return c
	}
	if c := cmp.Compare(uint16(a.FPort), b.Port); c != 0 {
		return c
	}
	if c := strings.Compare(s.rawStr(a.FName), string(b.Name)); c != 0 {
		return c
	}
	return 0
}

func cnfConfigCmpFlatKey36(s *ConfigSnapshot, a, b flatKeyHostKey) int {
	_ = s
	if c := cnfrt.CompareAddr(cnfrt.DecodeAddr(a.FAddr, s.zoned), cnfrt.DecodeAddr(b.FAddr, s.zoned)); c != 0 {
		return c
	}
	if c := cmp.Compare(a.FPort, b.FPort); c != 0 {
		return c
	}
	if c := strings.Compare(s.rawStr(a.FName), s.rawStr(b.FName)); c != 0 {
		return c
	}
	return 0
}

func cnfConfigHashGoKey36(k HostKey, seed uint64) uint64 {
	h := cnfrt.HashUint64(3, seed)
	h = cnfrt.HashCombine(h, cnfrt.HashAddr(k.Addr, seed))
	h = cnfrt.HashCombine(h, cnfrt.HashUint64(uint64(k.Port), seed))
	h = cnfrt.HashCombine(h, cnfrt.HashString(string(k.Name), seed))
	return h
}

func cnfConfigHashFlatKey36(s *ConfigSnapshot, k flatKeyHostKey, seed uint64) uint64 {
	_ = s
	h := cnfrt.HashUint64(3, seed)
	h = cnfrt.HashCombine(h, cnfrt.HashAddr(cnfrt.DecodeAddr(k.FAddr, s.zoned), seed))
	h = cnfrt.HashCombine(h, cnfrt.HashUint64(uint64(k.FPort), seed))
	h = cnfrt.HashCombine(h, cnfrt.HashString(s.rawStr(k.FName), seed))
	return h
}

