// Len returns the number of entries.
func (m PrefixInt32MapView) Len() int { return int(m.cnfSpan.Len) }

func (m PrefixInt32MapView) cnfEntries() []flatKVPrefixInt32Map {
	if m.cnfSpan.Len == 0 {
		return nil
	}
	off := int(m.cnfSpan.Off)
	return m.cnfSnap.pool12[off : off+int(m.cnfSpan.Len)]
}

// Get returns the value stored for k.
func (m PrefixInt32MapView) Get(k netip.Prefix) (int32, bool) {
	kv := m.cnfEntries()
	lo, hi := 0, len(kv)
	for lo < hi {
		mid := int(uint(lo+hi) >> 1)
		switch c := cnfrt.ComparePrefix(cnfrt.DecodePrefix(kv[mid].K), k); {
		case c < 0:
			lo = mid + 1
		case c > 0:
			hi = mid
		default:
			val := kv[mid].V
			runtime.KeepAlive(m.cnfSnap)
			return val, true
		}
	}
	runtime.KeepAlive(m.cnfSnap)
	var zero int32
	return zero, false
}

