// HostKeyInt64HashMapView is a read-only view of a map[HostKey]int64.
type HostKeyInt64HashMapView struct {
	cnfSnap *ConfigSnapshot
	cnfSpan cnfrt.HashSpan
}

// IsNil reports whether the map is nil.
func (m HostKeyInt64HashMapView) IsNil() bool { return m.cnfSpan.KV.Off == cnfrt.NilSpanOff }

// Len returns the number of entries.
func (m HostKeyInt64HashMapView) Len() int { return int(m.cnfSpan.KV.Len) }

func (m HostKeyInt64HashMapView) cnfEntries() []flatKVHostKeyInt64HashMap {
	if m.cnfSpan.KV.Len == 0 {
		return nil
	}
	off := int(m.cnfSpan.KV.Off)
	return m.cnfSnap.pool13[off : off+int(m.cnfSpan.KV.Len)]
}

// Get returns the value stored for k.
func (m HostKeyInt64HashMapView) Get(k HostKey) (int64, bool) {
	kv := m.cnfEntries()
	if len(kv) > 0 {
		idx := m.cnfSnap.pool14[int(m.cnfSpan.Idx.Off) : int(m.cnfSpan.Idx.Off)+int(m.cnfSpan.Idx.Len)]
		mask := uint64(len(idx) - 1)
		h := cnfConfigHashGoKey36(k, m.cnfSnap.seed)
		for probe := range uint64(len(idx)) {
			slot := idx[(h+probe)&mask]
			if slot == 0 || int(slot) > len(kv) {
				break
			}
			if e := &kv[slot-1]; cnfConfigCmpKey36(m.cnfSnap, e.K, k) == 0 {
				val := e.V
				runtime.KeepAlive(m.cnfSnap)
				return val, true
			}
		}
	}
	runtime.KeepAlive(m.cnfSnap)
	var zero int64
	return zero, false
}

