func (f *configFreezer) reserve(next *uint32, limit uint32, n int) uint32 {
	off := *next
	if uint64(off)+uint64(n) > uint64(limit) {
		cnfrt.Fail(cnfrt.ErrConcurrentModification)
	}
	*next += uint32(n)
	return off
}

