func (f *configFreezer) e37(x map[HostKey]int64) cnfrt.HashSpan {
	if x == nil {
		return cnfrt.HashSpan{KV: cnfrt.NilSpan, Idx: cnfrt.NilSpan}
	}
	n := len(x)
	if n == 0 {
		return cnfrt.HashSpan{}
	}
	var keys []HostKey
	reuseBuf := true
	if n >= 256 {
		if f.cachedPos37 >= len(f.cached37) {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		keys = f.cached37[f.cachedPos37]
		f.cached37[f.cachedPos37] = nil
		f.cachedPos37++
		if len(keys) != n {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		reuseBuf = false
	} else {
		// Take the shared key buffer; a nested map of the same type finds it
		// empty and uses its own.
		keys = f.k37[:0]
		f.k37 = nil
		if cap(keys) < n {
			keys = make([]HostKey, 0, max(n, 2*cap(keys)))
		}
		for k := range x {
			keys = append(keys, k)
		}
		if len(keys) != n {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		slices.SortFunc(keys, cnfConfigCmpGoKey36)
	}
	off := f.reserve(&f.p13, f.c13, n)
	dst := f.s.pool13[off : int(off)+n]
	for i, k := range keys {
		v, ok := x[k]
		if !ok {
			cnfrt.Fail(cnfrt.ErrConcurrentModification)
		}
		dst[i].K = f.e36(k)
		dst[i].V = int64(v)
	}
	region := cnfrt.HashRegion(n)
	ioff := f.reserve(&f.p14, f.c14, region)
	idx := f.s.pool14[ioff : int(ioff)+region]
	mask := uint64(region - 1)
	for i, k := range keys {
		h := cnfConfigHashGoKey36(k, f.b.Seed)
		for j := h & mask; ; j = (j + 1) & mask {
			if idx[j] == 0 {
				idx[j] = uint32(i + 1)
				break
			}
		}
	}
	if reuseBuf {
		f.k37 = keys[:0]
	}
	return cnfrt.HashSpan{KV: cnfrt.Span32{Off: off, Len: uint32(n)}, Idx: cnfrt.Span32{Off: ioff, Len: uint32(region)}}
}

