func (v *configValidator) v29(x cnfrt.Span32, self uint32, tbl int) {
	if err := v.claims[4].Claim(x, -1, true); err != nil {
		v.failErr(err)
		return
	}
	if x.Len == 0 {
		return
	}
	kv := v.s.pool4[int(x.Off) : int(x.Off)+int(x.Len)]
	for i := range kv {
		e := &kv[i]
		if !v.str(e.K) || !v.debit(uint64(e.K.Len)+1) {
			return
		}
		if i > 0 && strings.Compare(v.s.rawStr(kv[i-1].K), v.s.rawStr(e.K)) >= 0 {
			v.fail("map keys not strictly ascending")
			return
		}
		v.str(e.V)
	}
}

func (v *configValidator) v30(x cnfrt.HashSpan, self uint32, tbl int) {
	if err := v.claims[5].Claim(x.KV, -1, true); err != nil {
		v.failErr(err)
		return
	}
	region := cnfrt.HashRegion(int(x.KV.Len))
	if err := v.claims[6].Claim(x.Idx, region, x.KV.Off == cnfrt.NilSpanOff); err != nil {
		v.failErr(err)
		return
	}
	var idx []uint32
	if region > 0 {
		idx = v.s.pool6[int(x.Idx.Off) : int(x.Idx.Off)+region]
		used := 0
		for _, slot := range idx {
			if slot > x.KV.Len {
				v.fail("hash index slot")
				return
			}
			if slot != 0 {
				used++
			}
		}
		// Exactly one slot per entry leaves at least half of the region
		// empty, so every probe sequence ends early.
		if used != int(x.KV.Len) {
			v.fail("hash index occupancy")
			return
		}
	}
	if x.KV.Len == 0 {
		return
	}
	kv := v.s.pool5[int(x.KV.Off) : int(x.KV.Off)+int(x.KV.Len)]
	for i := range kv {
		e := &kv[i]
		if !v.str(e.K) || !v.debit(uint64(e.K.Len)+1) {
			return
		}
		if i > 0 && strings.Compare(v.s.rawStr(kv[i-1].K), v.s.rawStr(e.K)) >= 0 {
			v.fail("map keys not strictly ascending")
			return
		}
	}
	// Every entry must be found by the probe sequence of its key, as Get
	// searches it, within a linear probe budget.
	mask := uint64(region - 1)
	var totalProbes uint64
	probeBudget := uint64(8*len(kv) + 64)
	for i := range kv {
		if !v.debit(uint64(kv[i].K.Len) + 1) {
			return
		}
		h := cnfrt.HashString(v.s.rawStr(kv[i].K), v.s.seed)
		found := false
		for probe := range uint64(region) {
			totalProbes++
			if totalProbes > probeBudget {
				v.fail("hash index probe budget exceeded")
				return
			}
			slot := idx[(h+probe)&mask]
			if slot == 0 {
				break
			}
			if slot == uint32(i+1) {
				found = true
				break
			}
		}
		if !found {
			v.fail("hash index does not locate a key")
			return
		}
	}
}

