// SchemaHashCNF implements cnfrt.SchemaHasher.
func (CompactEndpoint) SchemaHashCNF() uint64 { return SchemaHashConfig }

// PackEndpoint freezes src (as FreezeEndpoint does) into a CompactEndpoint.
func PackEndpoint(src *Endpoint, opts ...cnfrt.FreezeOption) (CompactEndpoint, error) {
	return packEndpoint(cnfrt.ModeDAG, src, opts)
}

// PackTreeEndpoint freezes src as a tree (as FreezeTreeEndpoint does) into a CompactEndpoint.
func PackTreeEndpoint(src *Endpoint, opts ...cnfrt.FreezeOption) (CompactEndpoint, error) {
	return packEndpoint(cnfrt.ModeTree, src, opts)
}

// PackCyclicEndpoint freezes src permitting directed cycles (as FreezeCyclicEndpoint
// does) into a CompactEndpoint.
func PackCyclicEndpoint(src *Endpoint, opts ...cnfrt.FreezeOption) (CompactEndpoint, error) {
	return packEndpoint(cnfrt.ModeCyclic, src, opts)
}

// packEndpoint freezes src into the pooled scratch snapshot of a freezer and
// encodes it, so that the only allocation is the encoded value itself.
func packEndpoint(mode cnfrt.FreezeMode, src *Endpoint, opts []cnfrt.FreezeOption) (c CompactEndpoint, err error) {
	if src == nil {
		return CompactEndpoint{}, cnfrt.ErrNilRoot
	}
	if mode != cnfrt.ModeTree {
		cnfrt.Escape(src)
	}
	f := configFreezerPool.Get().(*configFreezer)
	defer func() {
		cnfrt.Recover(recover(), &err)
		if err != nil {
			c = CompactEndpoint{}
		}
		f.reset()
		configFreezerPool.Put(f)
	}()
	f.b.Init(mode, 8, opts...)
	f.scratch = true
	f.b.ReuseStrBuf(f.strBuf)
	f.mn2(src)
	f.allocate()
	id := f.en2(src)
	f.finish()
	runtime.KeepAlive(src)
	if id != 1 {
		return CompactEndpoint{}, fmt.Errorf("%w: unexpected compact root ID %d", cnfrt.ErrBoundsViolation, id)
	}
	s := f.s
	var secBuf [34]cnfrt.Section
	secs := secBuf[:0]
	if len(s.nodesConfig) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 8, Tag: 0, Count: uint32(len(s.nodesConfig)), Data: cnfrt.ViewSliceLE(s.nodesConfig)})
	}
	if len(s.nodesTree) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 8, Tag: 1, Count: uint32(len(s.nodesTree)), Data: cnfrt.ViewSliceLE(s.nodesTree)})
	}
	if len(s.nodesEndpoint) > 1 {
		extra := s.nodesEndpoint[1:]
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 8, Tag: 2, Count: uint32(len(extra)), Data: cnfrt.ViewSliceLE(extra)})
	}
	if len(s.nodesUser) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 8, Tag: 3, Count: uint32(len(s.nodesUser)), Data: cnfrt.ViewSliceLE(s.nodesUser)})
	}
	if len(s.nodesGroup) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 4, Count: uint32(len(s.nodesGroup)), Data: cnfrt.ViewSliceLE(s.nodesGroup)})
	}
	if len(s.nodesCircle) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 8, Tag: 5, Count: uint32(len(s.nodesCircle)), Data: cnfrt.ViewSliceLE(s.nodesCircle)})
	}
	if len(s.nodesRect) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 8, Tag: 6, Count: uint32(len(s.nodesRect)), Data: cnfrt.ViewSliceLE(s.nodesRect)})
	}
	if len(s.nodesPolicy) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionTable, ElemAlign: 4, Tag: 7, Count: uint32(len(s.nodesPolicy)), Data: cnfrt.ViewSliceLE(s.nodesPolicy)})
	}
	if len(s.pool0) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 0, Count: uint32(len(s.pool0)), Data: cnfrt.ViewSliceLE(s.pool0)})
	}
	if len(s.pool1) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 1, Count: uint32(len(s.pool1)), Data: cnfrt.ViewSliceLE(s.pool1)})
	}
	if len(s.pool2) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 2, Count: uint32(len(s.pool2)), Data: cnfrt.ViewSliceLE(s.pool2)})
	}
	if len(s.pool3) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 3, Count: uint32(len(s.pool3)), Data: cnfrt.ViewSliceLE(s.pool3)})
	}
	if len(s.pool4) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 4, Count: uint32(len(s.pool4)), Data: cnfrt.ViewSliceLE(s.pool4)})
	}
	if len(s.pool5) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 5, Count: uint32(len(s.pool5)), Data: cnfrt.ViewSliceLE(s.pool5)})
	}
	if len(s.pool6) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 6, Count: uint32(len(s.pool6)), Data: cnfrt.ViewSliceLE(s.pool6)})
	}
	if len(s.pool7) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 7, Count: uint32(len(s.pool7)), Data: cnfrt.ViewSliceLE(s.pool7)})
	}
	if len(s.pool8) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 8, Count: uint32(len(s.pool8)), Data: cnfrt.ViewSliceLE(s.pool8)})
	}
	if len(s.pool9) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 9, Count: uint32(len(s.pool9)), Data: cnfrt.ViewSliceLE(s.pool9)})
	}
	if len(s.pool10) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 10, Count: uint32(len(s.pool10)), Data: cnfrt.ViewSliceLE(s.pool10)})
	}
	if len(s.pool11) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 11, Count: uint32(len(s.pool11)), Data: cnfrt.ViewSliceLE(s.pool11)})
	}
	if len(s.pool12) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 12, Count: uint32(len(s.pool12)), Data: cnfrt.ViewSliceLE(s.pool12)})
	}
	if len(s.pool13) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 13, Count: uint32(len(s.pool13)), Data: cnfrt.ViewSliceLE(s.pool13)})
	}
	if len(s.pool14) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 14, Count: uint32(len(s.pool14)), Data: cnfrt.ViewSliceLE(s.pool14)})
	}
	if len(s.pool15) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 15, Count: uint32(len(s.pool15)), Data: cnfrt.ViewSliceLE(s.pool15)})
	}
	if len(s.pool16) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 8, Tag: 16, Count: uint32(len(s.pool16)), Data: cnfrt.ViewSliceLE(s.pool16)})
	}
	if len(s.pool17) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 17, Count: uint32(len(s.pool17)), Data: cnfrt.ViewSliceLE(s.pool17)})
	}
	if len(s.pool18) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 2, Tag: 18, Count: uint32(len(s.pool18)), Data: cnfrt.ViewSliceLE(s.pool18)})
	}
	if len(s.pool19) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 19, Count: uint32(len(s.pool19)), Data: cnfrt.ViewSliceLE(s.pool19)})
	}
	if len(s.pool20) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 20, Count: uint32(len(s.pool20)), Data: cnfrt.ViewSliceLE(s.pool20)})
	}
	if len(s.pool21) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 21, Count: uint32(len(s.pool21)), Data: cnfrt.ViewSliceLE(s.pool21)})
	}
	if len(s.pool22) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 22, Count: uint32(len(s.pool22)), Data: cnfrt.ViewSliceLE(s.pool22)})
	}
	if len(s.pool23) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionPool, ElemAlign: 4, Tag: 23, Count: uint32(len(s.pool23)), Data: cnfrt.ViewSliceLE(s.pool23)})
	}
	if len(s.strBlob) > 0 {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionStrBlob, ElemAlign: 1, Count: uint32(len(s.strBlob)), Data: cnfrt.UnsafeStringBytes(s.strBlob)})
	}
	if ext := cnfrt.EncodeExt(s.locEntries, s.zoned); ext != nil {
		secs = append(secs, cnfrt.Section{Kind: cnfrt.SectionExt, ElemAlign: 1, Count: uint32(len(ext)), Data: ext})
	}
	var flags uint8
	var dictToken uint64
	if s.flags&cnfrt.FlagHasDict != 0 {
		flags |= cnfrt.SlimFlagDict
		dictToken = s.dict.Token()
	}
	if s.flags&cnfrt.FlagCyclicAllowed != 0 {
		flags |= cnfrt.SlimFlagCyclic
	}
	if s.seed != cnfrt.DefaultSeed && (len(s.pool6) > 0 || len(s.pool8) > 0 || len(s.pool14) > 0) {
		flags |= cnfrt.SlimFlagSeed
	}
	buf, err := cnfrt.AppendSlimCompact(nil, flags, cnfrt.ViewSliceLE(s.nodesEndpoint[:1]), dictToken, s.seed, SchemaHashConfig, compactEndpointSlimSpecs[:], secs)
	f.strBuf = f.b.StrBuf()
	if err != nil {
		return CompactEndpoint{}, err
	}
	return CompactEndpoint{cnfRaw: cnfrt.UnsafeSealBytes(buf)}, nil
}

// BorrowCompactEndpoint validates the compact prefix of raw and returns a CompactEndpoint that
// aliases raw without copying. It is intended for zero-copy reads inside
// callbacks such as SlabMap.Borrow and FrozenMap.Borrow; the returned value
// must not be retained beyond the lifetime of raw.
func BorrowCompactEndpoint(raw string) (CompactEndpoint, error) {
	s, err := cnfrt.CheckSlimCompactString(raw, 161, SchemaHashConfig)
	return CompactEndpoint{cnfRaw: s}, err
}

// BorrowCompactEndpointBytes is BorrowCompactEndpoint for a byte slice, without copying. The
// returned CompactEndpoint aliases raw: it is valid only while raw is neither
// modified nor reused, typically for the duration of a SlabMap.Borrow
// callback, and must not be retained beyond it. Use ParseCompactEndpoint on a copy
// to keep a value.
func BorrowCompactEndpointBytes(raw []byte) (CompactEndpoint, error) {
	s, err := cnfrt.CheckSlimCompactBytes(raw, 161, SchemaHashConfig)
	return CompactEndpoint{cnfRaw: s}, err
}

// ParseCompactEndpoint checks raw (as produced by Raw) and returns it as a CompactEndpoint. The
// embedded image is verified according to mode. With cnfrt.VerifyUntrusted
// a value that references a cnfrt.Dict is rejected with
// cnfrt.ErrDictRequired unless that Dict is passed with cnfrt.AllowDict.
func ParseCompactEndpoint(raw string, mode cnfrt.VerifyMode, opts ...cnfrt.ParseOption) (CompactEndpoint, error) {
	c := CompactEndpoint{cnfRaw: raw}
	if _, err := c.cnfLoad(mode, true, cnfrt.AllowedDict(opts)); err != nil {
		return CompactEndpoint{}, err
	}
	return c, nil
}

// cnfCheck verifies the structure of the compact prefix (version, size,
// schema hash, dictionary registration and the offsets used by direct
// getters).
func (c CompactEndpoint) cnfCheck() error {
	return cnfrt.CheckSlimCompactPrefix(c.cnfRaw, 161, SchemaHashConfig)
}

func (c CompactEndpoint) cnfU32(off int) uint32 {
	return binary.LittleEndian.Uint32([]byte(c.cnfRaw[off : off+4]))
}

func (c CompactEndpoint) cnfExt() string {
	s := c.cnfRaw
	if len(s) < 173 || s[0]&cnfrt.SlimFlagExt == 0 {
		return ""
	}
	p := 165
	if s[0]&cnfrt.SlimFlagDict != 0 {
		p += cnfrt.SlimDictTokenSize
	}
	h := s[p : p+8]
	off := int(binary.LittleEndian.Uint32([]byte(h[0:4])))
	l := int(binary.LittleEndian.Uint32([]byte(h[4:8])))
	return s[off : off+l]
}

func (c CompactEndpoint) cnfTime(off int) time.Time {
	b := c.cnfRaw[off : off+16]
	sec := int64(binary.LittleEndian.Uint64([]byte(b[0:8])))
	meta := binary.LittleEndian.Uint64([]byte(b[8:16]))
	if (meta>>30)&3 == cnfrt.LocUTC {
		return time.Unix(sec, int64(meta&0x3fffffff)).UTC()
	}
	return cnfrt.DecodeCompactTime(sec, meta, c.cnfExt())
}

func (c CompactEndpoint) cnfAddr(off int) netip.Addr {
	f := cnfrt.CompactFlatAddr(c.cnfRaw, off)
	if f.Kind != cnfrt.AddrV6Zoned {
		return cnfrt.DecodeAddr(f, nil)
	}
	return cnfrt.DecodeCompactAddr(f, c.cnfExt())
}

func (c CompactEndpoint) cnfLoad(mode cnfrt.VerifyMode, checkCRC bool, allow *cnfrt.Dict) (*ConfigSnapshot, error) {
	data := cnfrt.UnsafeStringBytes(c.cnfRaw)
	if mode >= cnfrt.VerifyUntrusted {
		data = cnfrt.AlignedCopy(data)
	}
	var infoBuf [34]cnfrt.SectionInfo
	h, dict, infos, err := cnfrt.ParseSlimCompact(data, 160, SchemaHashConfig, 2, compactEndpointSlimSpecs[:], mode, checkCRC, allow, infoBuf[:0])
	if err != nil {
		return nil, err
	}
	s := &ConfigSnapshot{flags: h.Flags, seed: h.HashSeed, rootTable: h.RootTable, rootID: h.RootID, dict: dict, dictStrs: dict.Chunks()}
	if err := cnfrt.DecodeSliceLE(s.inlineRootEndpoint[:], data[1:161]); err != nil {
		return nil, err
	}
	s.nodesEndpoint = s.inlineRootEndpoint[:]
	for _, in := range infos {
		switch {
		case in.Kind == cnfrt.SectionTable && in.Tag == 0:
			s.nodesConfig, err = unsafemmap.Cast[flatConfig](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 1:
			s.nodesTree, err = unsafemmap.Cast[flatTree](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 2:
			extra, castErr := unsafemmap.Cast[flatEndpoint](data, in)
			if castErr != nil {
				return nil, castErr
			}
			nodes := make([]flatEndpoint, 1+len(extra))
			nodes[0] = s.inlineRootEndpoint[0]
			copy(nodes[1:], extra)
			s.nodesEndpoint = nodes
		case in.Kind == cnfrt.SectionTable && in.Tag == 3:
			s.nodesUser, err = unsafemmap.Cast[flatUser](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 4:
			s.nodesGroup, err = unsafemmap.Cast[flatGroup](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 5:
			s.nodesCircle, err = unsafemmap.Cast[flatCircle](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 6:
			s.nodesRect, err = unsafemmap.Cast[flatRect](data, in)
		case in.Kind == cnfrt.SectionTable && in.Tag == 7:
			s.nodesPolicy, err = unsafemmap.Cast[flatPolicy](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 0:
			s.pool0, err = unsafemmap.Cast[cnfrt.Span32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 1:
			s.pool1, err = unsafemmap.Cast[int64](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 2:
			s.pool2, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 3:
			s.pool3, err = unsafemmap.Cast[flatMeta](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 4:
			s.pool4, err = unsafemmap.Cast[flatKVStringStringMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 5:
			s.pool5, err = unsafemmap.Cast[flatKVStringFloat64HashMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 6:
			s.pool6, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 7:
			s.pool7, err = unsafemmap.Cast[flatKVInt64UserHashMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 8:
			s.pool8, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 9:
			s.pool9, err = unsafemmap.Cast[flatKVFloat64StringMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 10:
			s.pool10, err = unsafemmap.Cast[flatKVBoolInt32Map](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 11:
			s.pool11, err = unsafemmap.Cast[flatKVAddrStringMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 12:
			s.pool12, err = unsafemmap.Cast[flatKVPrefixInt32Map](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 13:
			s.pool13, err = unsafemmap.Cast[flatKVHostKeyInt64HashMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 14:
			s.pool14, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 15:
			s.pool15, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 16:
			s.pool16, err = unsafemmap.Cast[flatOptInt64](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 17:
			s.pool17, err = unsafemmap.Cast[cnfrt.VariantTag](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 18:
			s.pool18, err = unsafemmap.Cast[int16](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 19:
			s.pool19, err = unsafemmap.Cast[cnfrt.Span32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 20:
			s.pool20, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 21:
			s.pool21, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 22:
			s.pool22, err = unsafemmap.Cast[flatKVStringStringSliceMap](data, in)
		case in.Kind == cnfrt.SectionPool && in.Tag == 23:
			s.pool23, err = unsafemmap.Cast[uint32](data, in)
		case in.Kind == cnfrt.SectionStrBlob && in.Tag == 0:
			s.strBlob = unsafemmap.String(data, in)
		case in.Kind == cnfrt.SectionExt && in.Tag == 0:
			s.locEntries, s.zoned, err = cnfrt.DecodeExt(cnfrt.SectionData(data, in))
			if err == nil {
				s.locs = (&cnfrt.LocTable{Entries: s.locEntries}).Locations()
			}
		default:
			err = fmt.Errorf("%w: unexpected section kind %d tag %d", cnfrt.ErrCorruptHeader, in.Kind, in.Tag)
		}
		if err != nil {
			return nil, err
		}
	}
	if mode >= cnfrt.VerifyUntrusted {
		if err := s.validate(); err != nil {
			return nil, err
		}
	}
	return s, nil
}

// IsZero reports whether c is the zero value.
func (c CompactEndpoint) IsZero() bool { return c.cnfRaw == "" }

// UsesDict reports whether c stores any strings in a process-local cnfrt.Dict.
func (c CompactEndpoint) UsesDict() bool {
	return len(c.cnfRaw) > 0 && c.cnfRaw[0]&cnfrt.SlimFlagDict != 0
}

// Detach returns a self-contained CompactEndpoint with all dictionary strings
// materialized into its local string blob. If c does not use a dictionary,
// Detach returns c. By default the result keeps the hash seed of c
// (DefaultSeed unless c carries an explicit seed) and time.Local, so
// detaching the same value twice yields identical bytes; caller opts
// override those defaults except that WithDict is always cleared so the
// result never references a cnfrt.Dict. It returns cnfrt.ErrUnknownDict
// if the dictionary of c has been closed.
func (c CompactEndpoint) Detach(opts ...cnfrt.FreezeOption) (CompactEndpoint, error) {
	if !c.UsesDict() {
		return c, nil
	}
	v, err := c.Unpack()
	if err != nil || v == nil {
		return CompactEndpoint{}, err
	}
	merged := make([]cnfrt.FreezeOption, 0, len(opts)+3)
	merged = append(merged, cnfrt.WithHashSeed(cnfrt.SlimCompactSeed(c.cnfRaw, 161)), cnfrt.WithPreserveLocal())
	merged = append(merged, opts...)
	merged = append(merged, cnfrt.WithDict(nil))
	mode := cnfrt.ModeDAG
	if c.cnfRaw[0]&cnfrt.SlimFlagCyclic != 0 {
		mode = cnfrt.ModeCyclic
	}
	return packEndpoint(mode, v, merged)
}

// Raw returns the encoded value. It can be stored and later passed to
// ParseCompactEndpoint.
func (c CompactEndpoint) Raw() string { return c.cnfRaw }

// Equal reports whether c and o hold identical encodings.
func (c CompactEndpoint) Equal(o CompactEndpoint) bool { return c.cnfRaw == o.cnfRaw }

// View returns a view of the root over the embedded image. The image is
// not copied, but a snapshot header is allocated; the direct getters of
// CompactEndpoint do not allocate. View panics if c is corrupt or references a closed
// cnfrt.Dict (use TryView to get an error instead), and returns the zero
// view for the zero value.
func (c CompactEndpoint) View() EndpointView {
	if c.cnfRaw == "" {
		return EndpointView{}
	}
	s, err := c.cnfLoad(cnfrt.VerifyTrustedHeader, false, nil)
	if err != nil {
		panic(err)
	}
	return s.view2(s.rootID)
}

// TryView is like View but returns an error instead of panicking:
// cnfrt.ErrUnknownDict if c references a closed cnfrt.Dict, or a header
// error if c is corrupt.
func (c CompactEndpoint) TryView() (EndpointView, error) {
	if c.cnfRaw == "" {
		return EndpointView{}, nil
	}
	if err := c.cnfCheck(); err != nil {
		return EndpointView{}, err
	}
	s, err := c.cnfLoad(cnfrt.VerifyTrustedHeader, false, nil)
	if err != nil {
		return EndpointView{}, err
	}
	return s.view2(s.rootID), nil
}

// Snapshot loads the embedded image as a snapshot, verified according to
// mode; see ParseCompactEndpoint for the options.
func (c CompactEndpoint) Snapshot(mode cnfrt.VerifyMode, opts ...cnfrt.ParseOption) (*ConfigSnapshot, error) {
	return c.cnfLoad(mode, true, cnfrt.AllowedDict(opts))
}

// Unpack rebuilds the original Endpoint. It returns cnfrt.ErrUnknownDict if c
// references a closed cnfrt.Dict.
func (c CompactEndpoint) Unpack() (*Endpoint, error) {
	if c.cnfRaw == "" {
		return nil, nil
	}
	s, err := c.Snapshot(cnfrt.VerifyTrustedHeader)
	if err != nil {
		return nil, err
	}
	return s.view2(s.rootID).Unfreeze()
}

// SizeCNF implements cnfrt.SelfCodec.
func (c CompactEndpoint) SizeCNF() int { return len(c.cnfRaw) }

// AppendCNF implements cnfrt.SelfCodec.
func (c CompactEndpoint) AppendCNF(dst []byte) []byte { return append(dst, c.cnfRaw...) }

// DecodeCNF implements cnfrt.SelfDecoder. It checks the compact prefix;
// use ParseCompactEndpoint to verify the embedded image as well. src is retained.
func (c *CompactEndpoint) DecodeCNF(src string) error {
	s, err := cnfrt.CheckSlimCompactString(src, 161, SchemaHashConfig)
	if err == nil {
		c.cnfRaw = s
	}
	return err
}

// CodecCNF implements cnfrt.CodecProvider. Maps such as cnfrt.FrozenMap and
// cnfrt.SlabMap use the returned codec for CompactEndpoint values by default.
func (CompactEndpoint) CodecCNF() cnfrt.Codec[CompactEndpoint] { return compactEndpointCodec{} }

// compactEndpointCodec is the cnfrt.Codec of CompactEndpoint. It also implements
// cnfrt.UntrustedValidator, verifying the embedded image completely and
// rejecting values that reference a cnfrt.Dict, and cnfrt.AlignedCodec,
// so that stored values keep their image 8-byte aligned.
type compactEndpointCodec struct{}

func (compactEndpointCodec) Size(c CompactEndpoint) int { return len(c.cnfRaw) }

func (compactEndpointCodec) Append(dst []byte, c CompactEndpoint) []byte {
	return append(dst, c.cnfRaw...)
}

func (compactEndpointCodec) Decode(src string) (CompactEndpoint, error) {
	s, err := cnfrt.CheckSlimCompactString(src, 161, SchemaHashConfig)
	return CompactEndpoint{cnfRaw: s}, err
}

func (compactEndpointCodec) ValidateUntrusted(src string) error {
	if src == "" {
		return nil
	}
	_, err := ParseCompactEndpoint(src, cnfrt.VerifyUntrusted)
	return err
}

func (compactEndpointCodec) AlignCNF() int { return 8 }

// Name returns the Name field of the root without allocating.
func (c CompactEndpoint) Name() string {
	s := c.cnfRaw
	if len(s) < 165 {
		return ""
	}
	o, l := cnfrt.U32S(s[25:]), cnfrt.U32S(s[29:])
	if o >= cnfrt.DictSpanBit {
		if l == 0 {
			return ""
		}
		return cnfrt.ResolveDictSpan(s, 165, o, l)
	}
	i := int(cnfrt.U32S(s[161:])) + int(o)
	return s[i : i+int(l)]
}

// NameEquals reports whether the Name field equals v without allocating.
func (c CompactEndpoint) NameEquals(v string) bool {
	s := c.cnfRaw
	if len(s) < 165 {
		return v == ""
	}
	o, l := cnfrt.U32S(s[25:]), cnfrt.U32S(s[29:])
	if o >= cnfrt.DictSpanBit {
		if l == 0 {
			return v == ""
		}
		return cnfrt.ResolveDictSpan(s, 165, o, l) == v
	}
	i := int(cnfrt.U32S(s[161:])) + int(o)
	return s[i:i+int(l)] == v
}

// NameLen returns the length of the Name field without allocating.
func (c CompactEndpoint) NameLen() int {
	if c.cnfRaw == "" {
		return 0
	}
	return int(c.cnfU32(29))
}

// Port returns the Port field of the root without allocating.
func (c CompactEndpoint) Port() uint16 {
	if c.cnfRaw == "" {
		var zero uint16
		return zero
	}
	return binary.LittleEndian.Uint16([]byte(c.cnfRaw[89:91]))
}

// Weight returns the Weight field of the root without allocating.
func (c CompactEndpoint) Weight() float64 {
	if c.cnfRaw == "" {
		var zero float64
		return zero
	}
	return math.Float64frombits(binary.LittleEndian.Uint64([]byte(c.cnfRaw[1:9])))
}

// Up returns the Up field of the root without allocating.
func (c CompactEndpoint) Up() bool {
	if c.cnfRaw == "" {
		var zero bool
		return zero
	}
	return (c.cnfRaw[139] != 0)
}

// Addr returns the Addr field of the root without allocating.
func (c CompactEndpoint) Addr() netip.Addr {
	if c.cnfRaw == "" {
		var zero netip.Addr
		return zero
	}
	return c.cnfAddr(91)
}

// Prefix returns the Prefix field of the root without allocating.
func (c CompactEndpoint) Prefix() netip.Prefix {
	if c.cnfRaw == "" {
		var zero netip.Prefix
		return zero
	}
	return cnfrt.DecodePrefix(cnfrt.CompactFlatPrefix(c.cnfRaw, 140))
}

// AP returns the AP field of the root without allocating.
func (c CompactEndpoint) AP() netip.AddrPort {
	if c.cnfRaw == "" {
		var zero netip.AddrPort
		return zero
	}
	return netip.AddrPortFrom(c.cnfAddr(111), binary.LittleEndian.Uint16([]byte(c.cnfRaw[131:133])))
}

// Seen returns the Seen field of the root without allocating.
func (c CompactEndpoint) Seen() time.Time {
	if c.cnfRaw == "" {
		var zero time.Time
		return zero
	}
	return c.cnfTime(9)
}

// Opt returns the Opt field of the root and whether it is set.
func (c CompactEndpoint) Opt() (int32, bool) {
	if c.cnfRaw == "" {
		var zero int32
		return zero, false
	}
	if !(c.cnfRaw[160]&(1<<0) != 0) {
		var zero int32
		return zero, false
	}
	return int32(binary.LittleEndian.Uint32([]byte(c.cnfRaw[33:37]))), true
}

// OptName returns the OptName field of the root and whether it is set.
func (c CompactEndpoint) OptName() (string, bool) {
	s := c.cnfRaw
	if len(s) < 165 || s[160]&(1<<1) == 0 {
		return "", false
	}
	o, l := cnfrt.U32S(s[37:]), cnfrt.U32S(s[41:])
	if o >= cnfrt.DictSpanBit {
		if l == 0 {
			return "", true
		}
		return cnfrt.ResolveDictSpan(s, 165, o, l), true
	}
	i := int(cnfrt.U32S(s[161:])) + int(o)
	return s[i : i+int(l)], true
}

// Arr returns the Arr field of the root without allocating.
func (c CompactEndpoint) Arr() [2]uint16 {
	if c.cnfRaw == "" {
		var zero [2]uint16
		return zero
	}
	_ = c.cnfRaw[138] // one bounds check for all reads below
	return [2]uint16{binary.LittleEndian.Uint16([]byte(c.cnfRaw[135:137])), binary.LittleEndian.Uint16([]byte(c.cnfRaw[137:139]))}
}

// Blob returns the Blob field of the root without allocating.
func (c CompactEndpoint) Blob() string {
	s := c.cnfRaw
	if len(s) < 165 {
		return ""
	}
	o, l := cnfrt.U32S(s[45:]), cnfrt.U32S(s[49:])
	if o >= cnfrt.DictSpanBit {
		if l == 0 {
			return ""
		}
		return cnfrt.ResolveDictSpan(s, 165, o, l)
	}
	i := int(cnfrt.U32S(s[161:])) + int(o)
	return s[i : i+int(l)]
}

// BlobEquals reports whether the Blob field equals v without allocating.
func (c CompactEndpoint) BlobEquals(v string) bool {
	s := c.cnfRaw
	if len(s) < 165 {
		return v == ""
	}
	o, l := cnfrt.U32S(s[45:]), cnfrt.U32S(s[49:])
	if o >= cnfrt.DictSpanBit {
		if l == 0 {
			return v == ""
		}
		return cnfrt.ResolveDictSpan(s, 165, o, l) == v
	}
	i := int(cnfrt.U32S(s[161:])) + int(o)
	return s[i:i+int(l)] == v
}

// BlobLen returns the length of the Blob field without allocating.
func (c CompactEndpoint) BlobLen() int {
	if c.cnfRaw == "" {
		return 0
	}
	return int(c.cnfU32(49))
}

// BlobIsNil reports whether the Blob field is nil.
func (c CompactEndpoint) BlobIsNil() bool {
	if c.cnfRaw == "" {
		return true
	}
	return c.cnfU32(45) == cnfrt.NilSpanOff
}

// Fee decodes the Fee field of the root.
func (c CompactEndpoint) Fee() (Money, error) {
	s := c.cnfRaw
	if len(s) < 165 {
		var zero Money
		return zero, nil
	}
	o, l := cnfrt.U32S(s[81:]), cnfrt.U32S(s[85:])
	var raw string
	if o >= cnfrt.DictSpanBit {
		if l != 0 {
			raw = cnfrt.ResolveDictSpan(s, 165, o, l)
		}
	} else {
		i := int(cnfrt.U32S(s[161:])) + int(o)
		raw = s[i : i+int(l)]
	}
	return cnfrt.CodecValue[Money, MoneyCodec]{Raw: raw}.Decode()
}
